/* Original bilingual lessons. Commands are optional instruments, never learning objectives. */
window.GITHUB_COURSE = (() => {
  const B = (en, es) => ({ en, es });
  const F = (title, text, rule) => ({ title, text, rule });
  const Q = (question, options, correct, explanation) => ({ question, options, correct, explanation });
  const S = (title, text, expected, command = '') => ({ title, text, expected, command });
  const units = [B('How to learn here', 'Cómo aprender acá'), B('Remember a project', 'Recordar un proyecto'), B('Work in parallel', 'Trabajar en paralelo'), B('Agree on a change', 'Acordar un cambio'), B('Trust a change', 'Confiar en un cambio'), B('Deliver with context', 'Entregar con contexto')];
  const lessons = [];
  function add(unit, slug, title, intro, frames, experiment, quiz, lab, source, mode = 'local') {
    lessons.push({ id: lessons.length, unit, slug, title, intro, frames, experiment, quiz, lab, source, mode, visual: slug });
  }
  function local(name, prediction, observation, explanation) {
    return [
      S(B('Predict before looking', 'Predecí antes de mirar'), prediction, B('Write your prediction and the reason. An incorrect prediction is useful evidence.', 'Anotá tu predicción y el motivo. Una predicción incorrecta es evidencia útil.')),
      S(B('Run the experiment', 'Ejecutá el experimento'), B('Extract the kit and open a terminal in labs. The helper runs real Git in a new folder under labs/runs and prints every operation. It needs Git and Node.js. Read the action before its syntax; you do not need to memorize it.', 'Descomprimí el kit y abrí una terminal en labs. El asistente ejecuta Git real en una carpeta nueva dentro de labs/runs e imprime cada operación. Necesita Git y Node.js. Leé la acción antes que la sintaxis; no hace falta memorizarla.'), B('A new experiment path, Git output and PASS lines. A failure stops the experiment; keep the output to investigate.', 'Una ruta nueva de experimento, salidas de Git y líneas PASS. Una falla detiene el experimento; conservá la salida para investigar.'), 'node lab.mjs ' + name),
      S(B('Compare with your prediction', 'Compará con tu predicción'), observation, B('Point to concrete output or file contents. PASS is not a substitute for your explanation.', 'Señalá una salida o contenido de archivo concreto. PASS no reemplaza tu explicación.')),
      S(B('Explain the boundary', 'Explicá el límite'), explanation, B('Record four lines: prediction, observation, explanation, limit. Revisit tomorrow without the answer.', 'Registrá cuatro líneas: predicción, observación, explicación y límite. Volvé mañana sin mirar la respuesta.')),
    ];
  }

  add(0, 'before-you-start', B('Before you start', 'Antes de empezar'), B('Learn to predict what changes, where and for whom.', 'Aprendé a predecir qué cambia, dónde y para quién.'), [
    F(B('A question before a button', 'Una pregunta antes de un botón'), B('Our team maintains the Faro library guide. Two people change its opening hours. Before choosing an operation, ask which version each person has, what is recorded and what they want to share. Naming that state is the skill this course practices.', 'Nuestro equipo mantiene la guía de la biblioteca Faro. Dos personas cambian sus horarios. Antes de elegir una operación, preguntá qué versión tiene cada una, qué quedó registrado y qué quieren compartir. Reconocer ese estado es la habilidad que practica el curso.'), B('Explain the change in state before naming the command.', 'Explicá el cambio de estado antes de nombrar el comando.')),
    F(B('Three kinds of evidence', 'Tres tipos de evidencia'), B('The browser is an illustrative model. Local experiments execute real Git with no account or network. GitHub activities use your own practice repository online. A diagram, a local PASS and an actual review each demonstrate something different.', 'El navegador es un modelo ilustrativo. Los experimentos locales ejecutan Git real sin cuenta ni red. Las actividades de GitHub usan tu propio repositorio de práctica en línea. Un diagrama, un PASS local y una revisión real demuestran cosas distintas.'), B('Say whether you simulated, executed or observed.', 'Decí si simulaste, ejecutaste u observaste.')),
    F(B('Choose your depth', 'Elegí la profundidad'), B('Read the three scenes, change the model, predict an experiment and explain three checkpoint answers. Commands are available in an expandable block. Install Git 2.32 or later and Node.js 22 or later for the local kit. Without a GitHub account, use the explicitly labeled case studies in online lessons.', 'Leé las tres escenas, cambiá el modelo, predecí un experimento y explicá tres respuestas de control. Los comandos están en un bloque desplegable. Para el kit local instalá Git 2.32 o posterior y Node.js 22 o posterior. Sin cuenta de GitHub, usá los casos de estudio identificados en las lecciones en línea.'), B('Progress records your declaration, not automatic verification.', 'El avance registra tu declaración, no una verificación automática.')),
  ], B('Move the evidence selector. Which claims can each kind support?', 'Mové el selector de evidencia. ¿Qué afirmaciones puede sostener cada tipo?'), [
    Q(B('The model shows a successful merge. What have you verified?', 'El modelo muestra un merge exitoso. ¿Qué verificaste?'), [B('The real repository', 'El repositorio real'), B('Only the illustrated mechanism', 'Solo el mecanismo ilustrado'), B('The application works', 'Que la aplicación funciona')], 1, B('A model supports reasoning. Executing Git and testing the application require separate evidence.', 'Un modelo permite razonar. Ejecutar Git y probar la aplicación requieren evidencias separadas.')),
    Q(B('What should you remember after a lesson?', '¿Qué deberías recordar después de una lección?'), [B('Which state changed and why', 'Qué estado cambió y por qué'), B('Every flag in order', 'Cada opción en orden'), B('The exact commit identifier', 'El identificador exacto del commit')], 0, B('Syntax can be looked up. A prediction needs a mental model.', 'La sintaxis se puede consultar. Una predicción necesita un modelo mental.')),
    Q(B('Does completing the case study prove GitHub executed it?', '¿Completar el caso de estudio prueba que GitHub lo ejecutó?'), [B('Yes, if all answers are right', 'Sí, si todas las respuestas son correctas'), B('Yes, if the diagram is green', 'Sí, si el diagrama está verde'), B('No, it records reasoning only', 'No, registra solamente razonamiento')], 2, B('Keep a case study distinct from an online experiment in your notebook.', 'Distinguí el caso de estudio del experimento en línea en tu cuaderno.')),
  ], local('setup', B('Can a real repository exist entirely on your computer?', '¿Puede existir un repositorio real enteramente en tu computadora?'), B('Find the Git and Node versions, the new experiment folder and the initial commit. No remote was configured.', 'Buscá las versiones de Git y Node, la carpeta nueva y el commit inicial. No se configuró ningún remoto.'), B('Explain why installing Git is separate from creating a GitHub account.', 'Explicá por qué instalar Git es independiente de crear una cuenta de GitHub.')), 'github');

  add(1, 'git-and-github', B('Git and GitHub', 'Git y GitHub'), B('One records history. The other gives a team a place to collaborate.', 'Uno registra historia. El otro le da al equipo un lugar para colaborar.'), [
    F(B('The repository is more than a folder', 'El repositorio es más que una carpeta'), B('A working folder contains the files you edit. A Git repository also records versions and relationships between them. Saving guide.txt changes a file; recording a commit adds a historical checkpoint. These are separate acts.', 'Una carpeta de trabajo contiene los archivos que editás. Un repositorio Git también registra versiones y sus relaciones. Guardar guide.txt cambia un archivo; registrar un commit agrega un punto en la historia. Son actos distintos.'), B('A saved file is not necessarily recorded history.', 'Un archivo guardado no necesariamente quedó en la historia.')),
    F(B('Local first', 'Primero, lo local'), B('Git can record and inspect history without GitHub. GitHub hosts repositories and adds issues, pull requests and review. A local commit does not appear on GitHub until you transfer it. You can have several copies of a repository.', 'Git puede registrar y consultar historia sin GitHub. GitHub aloja repositorios y agrega issues, pull requests y revisión. Un commit local no aparece en GitHub hasta que lo transferís. Podés tener varias copias de un repositorio.'), B('Recording and sharing are different events.', 'Registrar y compartir son eventos distintos.')),
    F(B('Who sees the change?', '¿Quién ve el cambio?'), B('Ana records new library hours on her laptop. Bruno still sees the old version in his copy. Even when Ana publishes her branch, Bruno must obtain the new history. Treat each copy as a separate place with its own current knowledge.', 'Ana registra horarios nuevos en su laptop. Bruno todavía ve la versión anterior en su copia. Incluso cuando Ana publica su rama, Bruno tiene que obtener la historia nueva. Tratá cada copia como un lugar separado con su propio conocimiento actual.'), B('Always name the copy you are talking about.', 'Siempre nombrá la copia de la que hablás.')),
  ], B('Switch between local and shared. Does recording a commit transfer it?', 'Alterná entre local y compartido. ¿Registrar un commit lo transfiere?'), [
    Q(B('You commit offline. Where is the new history?', 'Hacés un commit sin conexión. ¿Dónde está la historia nueva?'), [B('In your local repository', 'En tu repositorio local'), B('On GitHub automatically', 'En GitHub automáticamente'), B('Only in your editor', 'Solo en tu editor')], 0, B('Git records locally; publishing is another operation.', 'Git registra localmente; publicar es otra operación.')),
    Q(B('Which object belongs to GitHub collaboration?', '¿Qué objeto pertenece a la colaboración de GitHub?'), [B('A local commit', 'Un commit local'), B('A pull request discussion', 'La conversación de un pull request'), B('A staging area', 'Un área de preparación')], 1, B('Git stores commits and staging state. GitHub adds the review conversation.', 'Git guarda commits y el estado de preparación. GitHub agrega la conversación de revisión.')),
    Q(B('Ana saved a file. Can Bruno see it already?', 'Ana guardó un archivo. ¿Bruno ya puede verlo?'), [B('Yes, if both use GitHub', 'Sí, si ambos usan GitHub'), B('Yes, if the name matches', 'Sí, si el nombre coincide'), B('No, saving alone does not share it', 'No, guardar por sí solo no lo comparte')], 2, B('An editor save has no synchronization guarantee.', 'Guardar en el editor no garantiza sincronización.')),
  ], local('local', B('Will a new commit require an internet connection or a remote?', '¿Un commit nuevo va a necesitar conexión o un remoto?'), B('Find two commits and an empty remote list. Inspect guide.txt in the printed folder.', 'Buscá dos commits y una lista de remotos vacía. Inspeccioná guide.txt en la carpeta indicada.'), B('Explain the difference between save, commit and publish using Ana and Bruno.', 'Explicá la diferencia entre guardar, hacer commit y publicar con Ana y Bruno.')), 'github');

  add(1, 'commits', B('Commits: snapshots with a reason', 'Commits: instantáneas con un motivo'), B('A version is content plus context and ancestry.', 'Una versión es contenido, contexto y ascendencia.'), [
    F(B('A coherent checkpoint', 'Un punto coherente'), B('Imagine photographing the whole library guide after correcting its hours. A commit records a snapshot of the tracked project, a message and metadata, with links to parent commits. Unchanged content can be reused internally; this is not a new full disk copy every time.', 'Imaginá fotografiar toda la guía después de corregir los horarios. Un commit registra una instantánea del proyecto seguido, un mensaje y metadatos, con enlaces a commits padres. Internamente se puede reutilizar contenido sin cambios; no es una copia completa nueva del disco cada vez.'), B('Think snapshot first; a diff compares snapshots.', 'Pensá primero en instantáneas; un diff compara instantáneas.')),
    F(B('The graph explains the story', 'El grafo explica la historia'), B('An arrow from a commit to its parent says which recorded state it follows. The initial commit has no parent. A typical commit has one; a merge commit can have more. Commit identifiers name objects, not a sequence of revision numbers.', 'Una flecha de un commit a su padre indica a qué estado registrado sigue. El inicial no tiene padre. Uno habitual tiene uno; un merge commit puede tener más. Los identificadores nombran objetos, no una secuencia de números de revisión.'), B('Read ancestry, not just timestamps.', 'Leé ascendencia, no solo fechas.')),
    F(B('A reason helps the next reader', 'El motivo ayuda a quien viene después'), B('“Fix hours after winter schedule change” helps a reviewer understand why a line moved. “Update file” does not. Group changes by purpose so a future teammate can explain, review or reverse one decision without untangling unrelated edits.', '«Corregir horarios por el cambio de invierno» ayuda a entender por qué cambió una línea. «Actualizar archivo» no. Agrupá cambios por propósito para que otra persona pueda explicar, revisar o revertir una decisión sin desenredar ediciones ajenas.'), B('One intelligible decision is a useful unit of history.', 'Una decisión entendible es una unidad útil de historia.')),
  ], B('Select each snapshot. Which file content belongs to it?', 'Seleccioná cada instantánea. ¿Qué contenido del archivo le corresponde?'), [
    Q(B('What is a diff?', '¿Qué es un diff?'), [B('A branch name', 'El nombre de una rama'), B('A comparison between states', 'Una comparación entre estados'), B('A backup of all GitHub data', 'Una copia de todos los datos de GitHub')], 1, B('The displayed change depends on which two states you compare.', 'El cambio mostrado depende de qué dos estados compares.')),
    Q(B('Two snapshots have identical files but different parents. Must they be the same commit?', 'Dos instantáneas tienen archivos idénticos y padres distintos. ¿Deben ser el mismo commit?'), [B('No, ancestry is part of the commit', 'No, la ascendencia forma parte del commit'), B('Yes, only files matter', 'Sí, solo importan los archivos'), B('Yes, if branch names match', 'Sí, si coinciden las ramas')], 0, B('A commit identifies content and metadata, including parent relationships.', 'Un commit identifica contenido y metadatos, incluidas las relaciones con padres.')),
    Q(B('Why separate an hours correction from a logo redesign?', '¿Por qué separar una corrección de horarios de un rediseño del logo?'), [B('Git cannot store both', 'Git no puede guardar ambos'), B('Each file needs its own repository', 'Cada archivo necesita un repositorio'), B('They are separate decisions to review or undo', 'Son decisiones distintas para revisar o deshacer')], 2, B('This is a collaboration choice, not a Git file limit.', 'Es una elección de colaboración, no un límite de archivos de Git.')),
  ], local('snapshots', B('After changing the hours, will the previous commit show the old or new hours?', 'Después de cambiar los horarios, ¿el commit anterior va a mostrar los viejos o los nuevos?'), B('Compare the old and current guide printed by Git. Then read the diff and parent identifier.', 'Compará la guía anterior y la actual que imprime Git. Después leé el diff y el identificador del padre.'), B('Explain why a diff and a snapshot answer different questions.', 'Explicá por qué un diff y una instantánea responden preguntas distintas.')), 'commits');

  add(1, 'staging', B('Three places for a change', 'Tres lugares para un cambio'), B('Editing, preparing and recording are separate decisions.', 'Editar, preparar y registrar son decisiones separadas.'), [
    F(B('Your desk', 'Tu mesa de trabajo'), B('The working tree is the set of files you currently edit. Ana corrects the hours and starts an unfinished note. Both changes are on her desk. She wants to record only the finished correction.', 'El working tree es el conjunto de archivos que editás ahora. Ana corrige los horarios y empieza una nota incompleta. Ambos cambios están en su mesa. Quiere registrar solo la corrección terminada.'), B('What is edited can exceed what should be committed.', 'Lo editado puede ser más que lo que conviene registrar.')),
    F(B('The next snapshot', 'La próxima instantánea'), B('The staging area, also called the index, holds the content selected for the next commit. It is a prepared version, not just a list of filenames. If you stage 10:00 then edit the file to 11:00, the prepared content is still 10:00 until you stage again.', 'El staging area, también llamado index, contiene lo elegido para el próximo commit. Es una versión preparada, no solo una lista de nombres de archivo. Si preparás 10:00 y después editás el archivo a 11:00, lo preparado sigue siendo 10:00 hasta que lo prepares de nuevo.'), B('Preparing captures content at that moment.', 'Preparar captura contenido de ese momento.')),
    F(B('Read both comparisons', 'Leé ambas comparaciones'), B('The ordinary diff compares your working files with the index. The staged diff compares the index with the current commit. In our example, one shows 10:00 to 11:00; the other shows 09:00 to 10:00. A normal commit records the index.', 'El diff común compara tus archivos de trabajo con el index. El diff preparado compara el index con el commit actual. En el ejemplo, uno muestra 10:00 a 11:00; el otro, 09:00 a 10:00. Un commit normal registra el index.'), B('Ask which two states the comparison uses.', 'Preguntá qué dos estados usa la comparación.')),
  ], B('Change the prepared version while the working file stays at 11:00. Predict the next commit.', 'Cambiá la versión preparada mientras el archivo queda en 11:00. Predecí el próximo commit.'), [
    Q(B('You stage 10:00, then save 11:00. What does a normal commit record?', 'Preparás 10:00 y después guardás 11:00. ¿Qué registra un commit normal?'), [B('11:00', '11:00'), B('Both versions in one file', 'Ambas versiones en un archivo'), B('10:00', '10:00')], 2, B('The index still holds 10:00. The later edit remains in the working tree.', 'El index todavía contiene 10:00. La edición posterior queda en el working tree.')),
    Q(B('Can a file have both staged and unstaged changes?', '¿Un archivo puede tener cambios preparados y sin preparar?'), [B('Yes, the stored versions can differ', 'Sí, las versiones guardadas pueden diferir'), B('No, it has exactly one state', 'No, tiene exactamente un estado'), B('Only after publishing', 'Solo después de publicar')], 0, B('The index and working tree can hold different content for the same path.', 'El index y el working tree pueden tener contenido diferente para la misma ruta.')),
    Q(B('Which comparison previews a normal commit?', '¿Qué comparación anticipa un commit normal?'), [B('Your files against GitHub', 'Tus archivos contra GitHub'), B('Index against current commit', 'Index contra commit actual'), B('Two branch names alphabetically', 'Dos nombres de rama alfabéticamente')], 1, B('That comparison isolates the prepared change.', 'Esa comparación aísla el cambio preparado.')),
  ], local('staging', B('The experiment prepares 10:00 and then saves 11:00. Predict the recorded hours.', 'El experimento prepara 10:00 y después guarda 11:00. Predecí los horarios registrados.'), B('Read working file = 11:00, index = 10:00, committed = 10:00. Compare both diffs.', 'Leé archivo de trabajo = 11:00, index = 10:00, registrado = 10:00. Compará ambos diffs.'), B('Explain this result without using the words add or commit as verbs.', 'Explicá el resultado sin usar add ni commit como verbos.')), 'staging');

  add(1, 'branches', B('Branches are movable names', 'Las ramas son nombres que se mueven'), B('A parallel line of work starts with a pointer.', 'Una línea de trabajo paralela empieza con un puntero.'), [
    F(B('Two names, one starting point', 'Dos nombres, un punto de partida'), B('main names our accepted history. Creating hours from main gives another name to the same commit. No new historical version is required just to create that branch. The names can move independently as work continues.', 'main nombra nuestra historia aceptada. Crear hours desde main le da otro nombre al mismo commit. Crear esa rama no requiere una versión histórica nueva. Los nombres pueden moverse de forma independiente al seguir trabajando.'), B('A branch points to a commit; it is not a folder copy.', 'Una rama apunta a un commit; no es una copia de carpeta.')),
    F(B('Where is the next commit going?', '¿Adónde va el próximo commit?'), B('HEAD usually identifies the current branch. While hours is checked out, a new commit advances hours and leaves main where it was. Switching branches changes the selected history and updates files as needed; Git can refuse if local edits would be overwritten.', 'HEAD suele identificar la rama actual. Con hours seleccionada, un commit nuevo adelanta hours y deja main donde estaba. Cambiar de rama selecciona otra historia y actualiza archivos cuando hace falta; Git puede negarse si sobrescribiría ediciones locales.'), B('Know your current branch before recording work.', 'Conocé tu rama actual antes de registrar trabajo.')),
    F(B('Names are agreements', 'Los nombres son acuerdos'), B('main is a convention, not a built-in quality guarantee. A branch named production can contain broken work. The team decides what each branch means and what evidence is needed to advance it. A branch is not access isolation.', 'main es una convención, no una garantía incorporada de calidad. Una rama llamada production puede contener trabajo roto. El equipo decide qué significa cada rama y qué evidencia necesita para avanzar. Una rama no aísla permisos de acceso.'), B('The name communicates intent; policy enforces it.', 'El nombre comunica intención; una política la hace cumplir.')),
  ], B('Advance the hours branch. Which name stays on the original commit?', 'Adelantá la rama hours. ¿Qué nombre queda en el commit original?'), [
    Q(B('Creating a branch at the current commit adds what?', '¿Qué agrega crear una rama en el commit actual?'), [B('A new name pointing at that commit', 'Un nombre nuevo que apunta a ese commit'), B('A new snapshot automatically', 'Una instantánea nueva automáticamente'), B('A GitHub repository', 'Un repositorio de GitHub')], 0, B('Names and snapshots are different objects in the mental model.', 'Nombres e instantáneas son objetos diferentes en el modelo mental.')),
    Q(B('A new commit on hours moves which branch?', '¿Qué rama mueve un commit nuevo en hours?'), [B('Every branch', 'Todas las ramas'), B('hours', 'hours'), B('Only main', 'Solo main')], 1, B('The current branch advances; other branch tips stay where they were.', 'Avanza la rama actual; las puntas de las otras quedan donde estaban.')),
    Q(B('Does main guarantee working code?', '¿main garantiza código que funciona?'), [B('Yes, Git tests it', 'Sí, Git lo prueba'), B('Yes, when it is the default', 'Sí, cuando es la predeterminada'), B('No, quality needs evidence and policy', 'No, la calidad necesita evidencia y políticas')], 2, B('Branch names do not execute tests or reviews.', 'Los nombres de rama no ejecutan pruebas ni revisiones.')),
  ], local('branches', B('Will main move when the helper records an hours change on another branch?', '¿Se va a mover main cuando el asistente registre un cambio de horarios en otra rama?'), B('Find main at the initial commit and hours at its child. Switching back restores the old hours.', 'Encontrá main en el commit inicial y hours en su hijo. Volver a main recupera los horarios anteriores.'), B('Draw the two pointers and HEAD. Explain what a branch deletion would remove.', 'Dibujá los dos punteros y HEAD. Explicá qué quitaría borrar una rama.')), 'branches');

  add(2, 'merging', B('Merging histories', 'Merge: unir historias'), B('Combine work using its shared starting point.', 'Combiná trabajo usando su punto de partida común.'), [
    F(B('One path is already inside another', 'Un camino ya está dentro del otro'), B('If main has not moved since hours branched off, main can advance to the tip of hours. This fast-forward needs no new merge commit. The existing commits already describe a continuous path.', 'Si main no avanzó desde que se creó hours, main puede avanzar hasta la punta de hours. Este fast-forward no necesita un merge commit nuevo. Los commits existentes ya describen un camino continuo.'), B('Fast-forward moves a name along existing history.', 'Fast-forward mueve un nombre por historia existente.')),
    F(B('Two paths have advanced', 'Avanzaron dos caminos'), B('Ana changes the hours while Bruno adds a contact file. The branches diverge. Git uses a shared ancestor and both tips to combine changes. A usual merge commit records the result with both tips as parents.', 'Ana cambia los horarios mientras Bruno agrega un archivo de contacto. Las ramas divergen. Git usa un ancestro compartido y ambas puntas para combinar cambios. Un merge commit habitual registra el resultado con ambas puntas como padres.'), B('A merge preserves both lines of ancestry.', 'Un merge conserva ambas líneas de ascendencia.')),
    F(B('Text fits; behavior may not', 'El texto encaja; el comportamiento quizá no'), B('Ana changes the opening hour to 10:00. Bruno advertises a workshop at 09:30 in another file. Git can combine those edits without a textual conflict. The resulting guide still contradicts itself. Test the meaning after combining the text.', 'Ana cambia la apertura a las 10:00. Bruno anuncia un taller a las 09:30 en otro archivo. Git puede combinar esas ediciones sin conflicto textual. La guía resultante igual se contradice. Probá el significado después de combinar el texto.'), B('No textual conflict does not mean no problem.', 'Sin conflicto textual no significa sin problema.')),
  ], B('Toggle divergence. Does integration need a new commit with two parents?', 'Alterná la divergencia. ¿La integración necesita un commit nuevo con dos padres?'), [
    Q(B('main is an ancestor of hours. What can a fast-forward do?', 'main es ancestro de hours. ¿Qué puede hacer un fast-forward?'), [B('Copy only the latest file', 'Copiar solo el último archivo'), B('Advance main to hours', 'Adelantar main hasta hours'), B('Erase hours history', 'Borrar la historia de hours')], 1, B('It moves the reference because the path already exists.', 'Mueve la referencia porque el camino ya existe.')),
    Q(B('A normal merge commit of two diverged branches has how many parents?', '¿Cuántos padres tiene un merge normal de dos ramas divergentes?'), [B('Zero', 'Cero'), B('One', 'Uno'), B('Two', 'Dos')], 2, B('The parents retain the two histories that were combined.', 'Los padres conservan las dos historias combinadas.')),
    Q(B('Git merged two files cleanly. What remains to verify?', 'Git hizo merge de dos archivos sin conflictos. ¿Qué falta verificar?'), [B('That their combined meaning works', 'Que su significado combinado funcione'), B('Whether Git created any history', 'Si Git creó alguna historia'), B('Nothing', 'Nada')], 0, B('Textual compatibility is weaker than behavioral correctness.', 'La compatibilidad textual es más débil que la corrección del comportamiento.')),
  ], local('merge', B('One branch edits hours, the other adds contact.txt. Predict the result and number of parents.', 'Una rama edita horarios y otra agrega contact.txt. Predecí el resultado y la cantidad de padres.'), B('Find both files in the merged snapshot and two parent identifiers. The helper also demonstrates a fast-forward separately.', 'Buscá ambos archivos en la instantánea del merge y dos identificadores de padres. El asistente también muestra un fast-forward por separado.'), B('Invent a contradiction that Git could merge without a conflict.', 'Inventá una contradicción de la que Git podría hacer merge sin conflicto.')), 'merging');

  add(2, 'conflicts', B('Conflicts are unanswered questions', 'Los conflictos son preguntas sin responder'), B('The tool finds ambiguity; people decide the meaning.', 'La herramienta encuentra ambigüedad; las personas deciden el significado.'), [
    F(B('One line, two intentions', 'Una línea, dos intenciones'), B('From the same 09:00 starting point, Ana writes 10:00 and Bruno writes 11:00. Both change the same line. Git cannot decide the library schedule. A conflict marks a choice that automatic text integration cannot safely make.', 'Desde el mismo inicio a las 09:00, Ana escribe 10:00 y Bruno 11:00. Ambos cambian la misma línea. Git no puede decidir el horario de la biblioteca. Un conflicto señala una elección que la integración automática de texto no puede hacer con seguridad.'), B('A conflict is information, not proof that history is lost.', 'Un conflicto es información, no prueba de que se perdió historia.')),
    F(B('Three versions matter', 'Importan tres versiones'), B('Read the shared base, the current side and the incoming side. “Ours” and “theirs” depend on the operation, not on who is morally right. Ask each author what they intended before editing the combined result.', 'Leé la base compartida, el lado actual y el entrante. «Ours» y «theirs» dependen de la operación, no de quién tiene razón. Preguntá qué pretendía cada autor antes de editar el resultado combinado.'), B('Compare intentions against the common base.', 'Compará intenciones contra la base común.')),
    F(B('Resolve, then verify', 'Resolvé y después verificá'), B('After deciding on 10:30, replace the conflict markers with the agreed text, prepare that result and finish the merge. Removing markers alone is not enough: confirm the guide is consistent. Aborting an unfinished merge is another choice when you need to reconsider.', 'Después de acordar 10:30, reemplazá las marcas del conflicto por el texto decidido, prepará el resultado y terminá el merge. Quitar marcas no alcanza: confirmá que la guía sea coherente. Abortar un merge pendiente es otra opción si necesitás reconsiderar.'), B('Resolution is a new decision with its own evidence.', 'La resolución es una decisión nueva con evidencia propia.')),
  ], B('Choose 10:00, 11:00 or an agreed 10:30. Does Git know which is correct for the library?', 'Elegí 10:00, 11:00 o un acuerdo a las 10:30. ¿Git sabe cuál es correcto para la biblioteca?'), [
    Q(B('Why does Git stop at a conflicting hours line?', '¿Por qué Git se detiene ante una línea de horarios en conflicto?'), [B('It needs a human choice between incompatible edits', 'Necesita una decisión humana entre ediciones incompatibles'), B('The repository was deleted', 'El repositorio se borró'), B('The internet disconnected', 'Se cortó internet')], 0, B('Both histories remain available; their intended combination is unresolved.', 'Ambas historias siguen disponibles; su combinación pretendida está sin resolver.')),
    Q(B('Is deleting all conflict markers sufficient?', '¿Alcanza con borrar todas las marcas del conflicto?'), [B('Yes, markers are the whole problem', 'Sí, las marcas son todo el problema'), B('No, check the chosen content and complete the merge', 'No, verificá el contenido elegido y terminá el merge'), B('Only if the file is short', 'Solo si el archivo es corto')], 1, B('A syntactically clean result can still be wrong.', 'Un resultado limpio de marcas igual puede estar mal.')),
    Q(B('Must the resolution exactly equal one side?', '¿La resolución tiene que coincidir exactamente con un lado?'), [B('Always', 'Siempre'), B('Only with two authors', 'Solo con dos autores'), B('No, it may express a new agreed result', 'No, puede expresar un resultado nuevo acordado')], 2, B('The merge result can incorporate a decision neither original side contained.', 'El resultado puede incorporar una decisión que ninguno de los lados contenía.')),
  ], local('conflict', B('Both branches replace the same hours line. Predict where automatic integration will stop.', 'Ambas ramas reemplazan la misma línea de horarios. Predecí dónde se detendrá la integración automática.'), B('Read the printed conflict markers before the helper resolves to 10:30. Find the final two-parent commit and clean working tree.', 'Leé las marcas impresas antes de que el asistente resuelva a 10:30. Buscá el commit final con dos padres y el working tree limpio.'), B('The helper supplies an agreed answer for demonstration. Explain how your real team would obtain that agreement.', 'El asistente aporta una respuesta acordada para la demostración. Explicá cómo obtendría ese acuerdo tu equipo real.')), 'merging');

  add(2, 'remotes', B('Remotes and independent copies', 'Remotos y copias independientes'), B('A remote is an address with a local nickname.', 'Un remoto es una dirección con un apodo local.'), [
    F(B('Clone makes another repository', 'Clonar crea otro repositorio'), B('A usual clone copies repository history and checks out a working version. It is not a live shared folder. Editing the clone does not edit the source. Special shallow or partial clones can copy less; our experiments use ordinary complete clones.', 'Un clon habitual copia historia del repositorio y prepara una versión de trabajo. No es una carpeta compartida en vivo. Editar el clon no edita el origen. Clones especiales superficiales o parciales pueden copiar menos; nuestros experimentos usan clones completos habituales.'), B('A clone is an independent place to work.', 'Un clon es un lugar independiente para trabajar.')),
    F(B('origin is a nickname', 'origin es un apodo'), B('A remote configuration associates a name such as origin with an address. That address can be on GitHub, another host or even a local disk. Naming it origin does not make it the official project or grant permission to write.', 'La configuración de un remoto asocia un nombre como origin con una dirección. Puede estar en GitHub, otro servidor o incluso un disco local. Llamarlo origin no lo convierte en el proyecto oficial ni da permiso para escribir.'), B('Location, authority and permission are separate facts.', 'Ubicación, autoridad y permiso son hechos separados.')),
    F(B('Your last observation', 'Tu última observación'), B('origin/main is normally a local remote-tracking reference: your last recorded view of main at origin. It can be stale while someone else publishes new work. Your local main, origin/main and the server’s main are three distinct references.', 'origin/main normalmente es una referencia local de seguimiento: tu última vista registrada de main en origin. Puede estar desactualizada mientras otra persona publica trabajo. Tu main local, origin/main y main en el servidor son tres referencias distintas.'), B('A remote-tracking reference is knowledge, not a live window.', 'Una referencia de seguimiento es conocimiento, no una ventana en vivo.')),
  ], B('Advance the remote while the local observation stays still. Which label becomes stale?', 'Adelantá el remoto mientras la observación local queda quieta. ¿Qué etiqueta queda desactualizada?'), [
    Q(B('Does editing a clone change the source repository immediately?', '¿Editar un clon cambia el repositorio de origen de inmediato?'), [B('Yes, it is shared storage', 'Sí, es almacenamiento compartido'), B('No, it is another repository', 'No, es otro repositorio'), B('Only on the same computer', 'Solo en la misma computadora')], 1, B('Transfer and integration are explicit operations.', 'Transferir e integrar son operaciones explícitas.')),
    Q(B('What does the name origin guarantee?', '¿Qué garantiza el nombre origin?'), [B('A local configured address, if it exists', 'Una dirección configurada localmente, si existe'), B('Write access', 'Permiso de escritura'), B('That it is GitHub', 'Que sea GitHub')], 0, B('The name is conventional and can be changed.', 'El nombre es convencional y se puede cambiar.')),
    Q(B('A teammate pushed. Is your origin/main necessarily current?', 'Una compañera publicó cambios. ¿Tu origin/main está necesariamente al día?'), [B('Yes, it updates in real time', 'Sí, se actualiza en tiempo real'), B('Yes, while the editor is open', 'Sí, mientras el editor esté abierto'), B('No, you may need to fetch', 'No, quizá necesites hacer fetch')], 2, B('Your local observation does not continually poll the remote.', 'Tu observación local no consulta el remoto continuamente.')),
  ], local('remotes', B('Two clones share one local remote. Will Bruno see Ana’s published change before fetching?', 'Dos clones comparten un remoto local. ¿Bruno verá el cambio publicado de Ana antes de hacer fetch (traer novedades)?'), B('Find three repository paths. Compare the remote tip with Bruno’s old origin/main.', 'Buscá tres rutas de repositorio. Compará la punta remota con el origin/main viejo de Bruno.'), B('Explain what the local bare repository simulates and what it does not test about GitHub permissions.', 'Explicá qué simula el repositorio bare local y qué no prueba sobre permisos de GitHub.')), 'remotes');

  add(2, 'sync', B('Fetch, integrate, publish', 'Fetch, integrar, publicar'), B('There is no single magical “sync” operation.', 'No hay una única operación mágica de «sincronizar».'), [
    F(B('Learn what changed', 'Enterate de qué cambió'), B('Fetching obtains objects and updates configured remote-tracking references. In the usual workflow it does not merge them into your current branch or edit your working files. You can inspect the new history before choosing how to integrate it.', 'Fetch obtiene objetos y actualiza referencias de seguimiento configuradas. En el flujo habitual no los integra en tu rama actual ni edita tus archivos de trabajo. Podés inspeccionar la historia nueva antes de elegir cómo integrarla.'), B('Obtaining information and adopting it are separate.', 'Obtener información y adoptarla son cosas separadas.')),
    F(B('Choose the integration', 'Elegí la integración'), B('Pull combines fetching with an integration step, whose policy may be fast-forward, merge or rebase depending on options and configuration. First ask whether your histories diverged. A fast-forward-only policy stops rather than silently resolving a divergence.', 'Pull combina fetch con un paso de integración cuya política puede ser fast-forward, merge o rebase según opciones y configuración. Primero preguntá si las historias divergieron. Una política de solo fast-forward se detiene ante la divergencia.'), B('Understand the policy behind a convenience button.', 'Entendé la política detrás de un botón conveniente.')),
    F(B('Publish without discarding others', 'Publicá sin descartar a otros'), B('A normal push proposes updating a remote reference with your history. If the remote has commits absent from your proposed path, a non-fast-forward rejection protects that work. Fetch, inspect and integrate; forcing is not the default remedy.', 'Un push normal propone actualizar una referencia remota con tu historia. Si el remoto tiene commits ausentes de tu camino propuesto, el rechazo por non-fast-forward protege ese trabajo. Hacé fetch, inspeccioná e integrá; forzar no es la solución predeterminada.'), B('A rejection can preserve someone else’s work.', 'Un rechazo puede preservar el trabajo de otra persona.')),
  ], B('Compare before fetch, after fetch and after integration. When do the working files change?', 'Compará antes de fetch, después de fetch y después de integrar. ¿Cuándo cambian los archivos de trabajo?'), [
    Q(B('A usual fetch updates origin/main. Does your main necessarily move?', 'Un fetch habitual actualiza origin/main. ¿Tu main se mueve necesariamente?'), [B('Yes', 'Sí'), B('Only if GitHub is public', 'Solo si GitHub es público'), B('No', 'No')], 2, B('Remote observation and current branch are different references.', 'La observación remota y la rama actual son referencias distintas.')),
    Q(B('A push is rejected because the remote advanced. What should you understand first?', 'Un push se rechaza porque el remoto avanzó. ¿Qué deberías entender primero?'), [B('How the two histories differ', 'Cómo difieren las dos historias'), B('How to bypass all checks', 'Cómo saltear todos los controles'), B('How to delete the remote', 'Cómo borrar el remoto')], 0, B('Inspecting ancestry reveals what work an update would retain or discard.', 'Inspeccionar ascendencia revela qué trabajo conservaría o descartaría una actualización.')),
    Q(B('Why can two pull buttons behave differently?', '¿Por qué dos botones de pull pueden comportarse distinto?'), [B('Branch names determine every behavior', 'Los nombres de rama determinan todo'), B('They can use different integration policies', 'Pueden usar políticas de integración distintas'), B('Git ignores configuration', 'Git ignora la configuración')], 1, B('Ask which operations and policies the interface invokes.', 'Preguntá qué operaciones y políticas invoca la interfaz.')),
  ], local('sync', B('Predict Bruno’s file after fetch and after integration. Then predict a stale push.', 'Predecí el archivo de Bruno después de fetch y después de integrar. Después predecí un push desactualizado.'), B('The helper checks that fetch leaves the working file unchanged, integration updates it, and a divergent push is rejected.', 'El asistente comprueba que fetch deja el archivo intacto, integrar lo actualiza y un push divergente es rechazado.'), B('Explain why “I downloaded the commits” need not mean “I am using them”.', 'Explicá por qué «descargué los commits» no necesariamente significa «los estoy usando».')), 'fetch');

  add(2, 'forks', B('Fork, clone and branch', 'Fork, clon y rama'), B('Three forms of separation answer different needs.', 'Tres formas de separación responden a necesidades distintas.'), [
    F(B('A branch stays in one repository', 'Una rama queda en un repositorio'), B('A branch gives a line of work a name within a repository. Teammates with suitable access can publish branches in the same GitHub repository. This is useful when the team shares the repository’s governance.', 'Una rama le da nombre a una línea de trabajo dentro de un repositorio. Integrantes con acceso adecuado pueden publicar ramas en el mismo repositorio de GitHub. Sirve cuando el equipo comparte la administración del repositorio.'), B('A new branch is not a new owner.', 'Una rama nueva no es un dueño nuevo.')),
    F(B('A fork creates another hosted home', 'Un fork crea otro lugar alojado'), B('A GitHub fork is another repository linked to the original in a fork network. You can propose a change from a branch in your fork without having write access to the original. Fork availability and permissions depend on repository visibility and organization policy.', 'Un fork de GitHub es otro repositorio vinculado al original en una red de forks. Podés proponer un cambio desde una rama de tu fork sin permiso de escritura en el original. La disponibilidad y los permisos dependen de la visibilidad y las políticas de la organización.'), B('Permission to propose does not imply permission to integrate.', 'Poder proponer no implica poder integrar.')),
    F(B('A clone gives you a local workspace', 'Un clon te da un lugar local'), B('You can clone your fork and configure origin to point to it, with upstream pointing to the original. Those names are conventions. Updating your fork or clone does not automatically update the original project.', 'Podés clonar tu fork y configurar origin hacia él y upstream hacia el original. Esos nombres son convenciones. Actualizar tu fork o clon no actualiza automáticamente el proyecto original.'), B('Draw the repositories before drawing branches inside them.', 'Dibujá los repositorios antes de dibujar las ramas adentro.')),
  ], B('Follow the proposed change from clone to fork to original. Which step needs the maintainer’s decision?', 'Seguí el cambio propuesto del clon al fork y al original. ¿Qué paso necesita la decisión de quien mantiene el proyecto?'), [
    Q(B('You want to propose a change without write access to the original. What can help?', 'Querés proponer un cambio sin escritura en el original. ¿Qué puede servir?'), [B('Renaming main', 'Renombrar main'), B('A fork, where allowed', 'Un fork, donde esté permitido'), B('Deleting your clone', 'Borrar tu clon')], 1, B('A fork gives you a hosted place to publish your proposal.', 'Un fork te da un lugar alojado donde publicar tu propuesta.')),
    Q(B('Does pushing to your fork change the original main?', '¿Publicar en tu fork cambia main en el original?'), [B('Yes, both are the same repository', 'Sí, ambos son el mismo repositorio'), B('Yes, if branch names match', 'Sí, si coinciden los nombres'), B('No', 'No')], 2, B('They are separate repositories with separate integration decisions.', 'Son repositorios separados con decisiones de integración separadas.')),
    Q(B('What is upstream?', '¿Qué es upstream?'), [B('A conventional remote name often used for the original', 'Un nombre convencional de remoto que suele señalar el original'), B('A required GitHub branch', 'Una rama obligatoria de GitHub'), B('An automatic permission grant', 'Una concesión automática de permiso')], 0, B('Read the configured address; do not infer authority from the nickname. In Git, upstream also names the remote branch that a local branch tracks.', 'Leé la dirección configurada; no deduzcas autoridad del apodo. En Git, upstream también nombra la rama remota que sigue tu rama local.')),
  ], local('forks', B('The helper models an original, a separate fork-like repository and a clone. Which tip changes when publishing to the second repository?', 'El asistente modela un original, otro repositorio semejante a un fork y un clon. ¿Qué punta cambia al publicar en el segundo repositorio?'), B('The fork-like repository advances while the original stays still. This local model does not create a GitHub fork network.', 'El repositorio semejante al fork avanza mientras el original queda quieto. Este modelo local no crea una red de forks de GitHub.'), B('Draw where origin and upstream point. State which GitHub features the local experiment cannot verify.', 'Dibujá adónde apuntan origin y upstream. Indicá qué funciones de GitHub no puede verificar el experimento local.')), 'forks');

  add(3, 'issues', B('Issues: agree on the problem', 'Issues: acordar el problema'), B('Describe an observable need before proposing an implementation.', 'Describí una necesidad observable antes de proponer una implementación.'), [
    F(B('A useful problem statement', 'Un planteo útil'), B('A visitor arrived at 09:00 and found the library closed. An issue can record the observation, expected result and reproduction context. “Fix everything” is hard to evaluate; “the guide must show the winter opening hour” gives the team a concrete question.', 'Una visitante llegó a las 09:00 y encontró la biblioteca cerrada. Un issue puede registrar observación, resultado esperado y contexto para reproducirlo. «Arreglar todo» es difícil de evaluar; «la guía debe mostrar el horario de invierno» da al equipo una pregunta concreta.'), B('Make success observable.', 'Hacé observable el éxito.')),
    F(B('Problem and solution evolve separately', 'Problema y solución evolucionan por separado'), B('The issue describes a need. A pull request can propose one solution. Discussion may reveal that both the guide and a workshop notice need updating. A single issue can motivate several changes; writing one does not modify files.', 'El issue describe una necesidad. Un pull request puede proponer una solución. La conversación puede revelar que hay que actualizar la guía y el aviso de un taller. Un issue puede motivar varios cambios; escribirlo no modifica archivos.'), B('A tracked intention is not an implemented change.', 'Una intención registrada no es un cambio implementado.')),
    F(B('Context that survives the conversation', 'Contexto que sobrevive a la conversación'), B('Record the affected guide, expected hours, a small acceptance checklist and who can confirm the real schedule. Labels and assignment help organize work, but their meaning comes from team practice. Closing an issue is a workflow event, not proof of correctness.', 'Registrá la guía afectada, horarios esperados, criterios de aceptación y quién puede confirmar el horario real. Etiquetas y asignación ayudan a organizar, pero su significado viene de la práctica del equipo. Cerrar un issue es un evento de trabajo, no prueba de corrección.'), B('Track the decision and the evidence supporting it.', 'Registrá la decisión y la evidencia que la sostiene.')),
  ], B('Compare a vague report with an observable one. Which could another person verify?', 'Compará un reporte vago con uno observable. ¿Cuál podría verificar otra persona?'), [
    Q(B('Which issue gives a reviewer a testable outcome?', '¿Qué issue da un resultado comprobable?'), [B('Improve the project', 'Mejorar el proyecto'), B('Do some GitHub work', 'Hacer trabajo en GitHub'), B('Show 10:00 in both guide and workshop notice', 'Mostrar 10:00 en la guía y el aviso del taller')], 2, B('Specific observable criteria make disagreements easier to resolve.', 'Los criterios observables específicos facilitan resolver desacuerdos.')),
    Q(B('Does opening an issue change the repository files?', '¿Abrir un issue cambia los archivos del repositorio?'), [B('No', 'No'), B('Yes, after assignment', 'Sí, después de asignarlo'), B('Yes, with a bug label', 'Sí, con una etiqueta de error')], 0, B('Planning records and file history are separate.', 'Los registros de planificación y la historia de archivos son independientes.')),
    Q(B('An issue is closed. What do you still need to assess?', 'Un issue está cerrado. ¿Qué todavía necesitás evaluar?'), [B('Whether its title has a number', 'Si su título tiene un número'), B('Whether the agreed outcome was demonstrated', 'Si se demostró el resultado acordado'), B('Whether it has enough labels', 'Si tiene suficientes etiquetas')], 1, B('Status is a signal; evidence supports the actual claim.', 'El estado es una señal; la evidencia sostiene la afirmación real.')),
  ], [
    S(B('Prepare a practice repository', 'Prepará un repositorio de práctica'), B('Online: create a repository you own named faro-practice with a README, choosing its visibility consciously. Visibility matters later: with GitHub Free, rulesets exist only in public repositories. Use only invented data. On main, edit the README so it says Open at 09:00, like the guide in the local experiments. Case study without an account: draw that repository on paper and label all later steps as a case study.', 'En línea: creá un repositorio propio llamado faro-practice con README y elegí su visibilidad conscientemente. La visibilidad importa después: con GitHub Free, los rulesets existen solo en repositorios públicos. Usá solo datos inventados. En main, editá el README para que diga Open at 09:00, como la guía de los experimentos locales. Caso sin cuenta: dibujá ese repositorio en papel e identificá todos los pasos posteriores como caso de estudio.'), B('A real practice repository whose main shows Open at 09:00, or a clearly labeled paper case.', 'Un repositorio de práctica real cuyo main muestra Open at 09:00, o un caso en papel identificado.')),
    S(B('Write the need', 'Escribí la necesidad'), B('Create an issue: “Winter hours disagree”. Include current 09:00, expected 10:00, affected README and the reason. In the paper case, write the same issue.', 'Creá un issue: «Los horarios de invierno no coinciden». Incluí 09:00 actual, 10:00 esperado, README afectado y el motivo. En el caso en papel, escribí el mismo issue.'), B('Someone else could tell whether the issue is resolved.', 'Otra persona podría determinar si el issue se resolvió.')),
    S(B('Define evidence', 'Definí la evidencia'), B('Add two criteria: the guide says 10:00 and no remaining notice says 09:00. Explain who can confirm the intended schedule. Record the issue number if online.', 'Agregá dos criterios: la guía dice 10:00 y ningún aviso restante dice 09:00. Explicá quién puede confirmar el horario pretendido. Anotá el número del issue si estás en línea.'), B('Criteria describe behavior and content, not button presses.', 'Los criterios describen comportamiento y contenido, no pulsaciones de botones.')),
    S(B('Challenge the scope', 'Cuestioná el alcance'), B('Would redesigning the logo belong in this issue? Write why. Leave the issue open for the next lesson; do not count a paper exercise as online verification.', '¿Rediseñar el logo pertenecería a este issue? Escribí por qué. Dejá el issue abierto para la próxima lección; no cuentes el ejercicio en papel como verificación en línea.'), B('One focused need that a later proposal can address.', 'Una necesidad enfocada que una propuesta posterior pueda resolver.')),
  ], 'issues', 'github');

  add(3, 'pull-requests', B('Pull requests: propose a difference', 'Pull requests: proponer una diferencia'), B('A proposal connects a source branch, a destination and a conversation.', 'Una propuesta conecta una rama de origen, un destino y una conversación.'), [
    F(B('Base and head', 'Base y head'), B('The base is the destination branch; the head is the source of the proposed work. For Faro, base main and head winter-hours means “bring these hours changes into main”. Reversing the comparison asks a different question.', 'La base es la rama de destino; head es el origen del trabajo propuesto. En Faro, base main y head winter-hours significa «incorporar estos horarios a main». Invertir la comparación hace otra pregunta.'), B('Name the source and destination before reviewing.', 'Nombrá origen y destino antes de revisar.')),
    F(B('A proposal can keep changing', 'Una propuesta puede seguir cambiando'), B('Opening a pull request does not merge it. New commits on its source branch can update the proposal. The review conversation therefore refers to evolving evidence. A draft communicates that the proposal is still being prepared.', 'Abrir un pull request no hace el merge. Commits nuevos en su rama de origen pueden actualizar la propuesta. La conversación de revisión se refiere entonces a evidencia que evoluciona. Un borrador comunica que la propuesta todavía está en preparación.'), B('A pull request is a conversation around a change.', 'Un pull request es una conversación alrededor de un cambio.')),
    F(B('Make the difference reviewable', 'Hacé revisable la diferencia'), B('State the problem, what changes, how you checked it and which issue motivated it. Read the changed files before asking others to review. A small proposal about hours is easier to reason about than one mixed with unrelated formatting.', 'Contá el problema, qué cambia, cómo lo comprobaste y qué issue lo motivó. Leé los archivos cambiados antes de pedir revisión. Una propuesta chica sobre horarios es más fácil de razonar que otra mezclada con formato ajeno al problema.'), B('Reviewability is part of the work.', 'Que el cambio sea revisable forma parte del trabajo.')),
  ], B('Switch the proposal from draft to open to merged. When does main actually change?', 'Pasá la propuesta de borrador a abierta y a merged. ¿Cuándo cambia main realmente?'), [
    Q(B('For winter-hours into main, which is the base?', 'Para incorporar winter-hours a main, ¿cuál es la base?'), [B('main', 'main'), B('winter-hours', 'winter-hours'), B('The author’s username', 'El nombre de quien lo escribió')], 0, B('The base receives the proposed integration.', 'La base recibe la integración propuesta.')),
    Q(B('Does opening a pull request update main?', '¿Abrir un pull request actualiza main?'), [B('Always', 'Siempre'), B('No', 'No'), B('Only if the diff is small', 'Solo si el diff es chico')], 1, B('Opening and merging are distinct events.', 'Abrir y hacer merge son eventos distintos.')),
    Q(B('You add a commit to the proposal branch. What should reviewers consider?', 'Agregás un commit a la rama propuesta. ¿Qué debería considerar quien revisa?'), [B('The proposal cannot change', 'La propuesta no puede cambiar'), B('The old approval proves all future changes', 'La aprobación anterior prueba todo cambio futuro'), B('The evidence being reviewed changed', 'Cambió la evidencia que se revisa')], 2, B('Review the current proposal, including changes since earlier feedback.', 'Revisá la propuesta actual, incluidos cambios posteriores a comentarios previos.')),
  ], [
    S(B('Start from the problem', 'Partí del problema'), B('Use faro-practice from lesson 10. In GitHub, create winter-hours from main. Paper case: draw both names at the same commit.', 'Usá faro-practice de la lección 10. En GitHub creá winter-hours desde main. Caso en papel: dibujá ambos nombres en el mismo commit.'), B('Two branch names; the accepted guide is unchanged.', 'Dos nombres de rama; la guía aceptada no cambió.')),
    S(B('Record one focused change', 'Registrá un cambio enfocado'), B('Edit README on winter-hours to say 10:00 and record the change on that branch. Predict which branch stays unchanged before saving. In the case, add a new snapshot only to winter-hours.', 'Editá README en winter-hours para que diga 10:00 y registrá el cambio en esa rama. Antes de guardar, predecí qué rama queda intacta. En el caso, agregá una instantánea nueva solo a winter-hours.'), B('winter-hours shows 10:00; main still has the previous guide.', 'winter-hours muestra 10:00; main todavía tiene la guía anterior.')),
    S(B('Open the proposal', 'Abrí la propuesta'), B('Open a draft pull request with base main and head winter-hours. Describe problem, change and evidence, and link the issue. In the case, write those same fields.', 'Abrí un pull request en borrador con base main y head winter-hours. Describí problema, cambio y evidencia y enlazá el issue. En el caso, escribí esos mismos campos.'), B('The diff contains only the intended hours change.', 'El diff contiene solo el cambio pretendido de horarios.')),
    S(B('Inspect without integrating', 'Inspeccioná sin integrar'), B('Compare main and the proposal. Read the changed files and leave it open for review. Explain why a pull request is not the same operation as Git pull.', 'Compará main y la propuesta. Leé los archivos cambiados y dejala abierta para revisar. Explicá por qué un pull request no es la misma operación que Git pull.'), B('A proposal exists while the destination remains unchanged.', 'Existe una propuesta mientras el destino sigue intacto.')),
  ], 'pulls', 'github');

  add(3, 'reviews', B('Review: evidence and agreement', 'Revisión: evidencia y acuerdo'), B('A green signal answers a specific question, not every question.', 'Una señal verde responde una pregunta específica, no todas.'), [
    F(B('Read as the next maintainer', 'Leé como quien mantendrá el proyecto'), B('Review the proposal’s purpose, changed content and evidence. Ask whether the library hours are correct and whether another notice contradicts them. A useful comment names a concrete concern and its consequence, rather than merely stating taste.', 'Revisá propósito, contenido cambiado y evidencia. Preguntá si los horarios son correctos y si otro aviso los contradice. Un comentario útil nombra una preocupación concreta y su consecuencia, en vez de expresar solamente gusto.'), B('Review the decision, not just the spelling.', 'Revisá la decisión, además de la ortografía.')),
    F(B('Human and automated checks', 'Controles humanos y automáticos'), B('A review may comment, approve or request changes. A test run checks assertions chosen by its author. Neither alone proves every requirement. For Faro, a script can find “10:00”, but a person must confirm that 10:00 is the intended opening time.', 'Una revisión puede comentar, aprobar o pedir cambios. Una prueba automática verifica afirmaciones elegidas por su autor. Ninguna demuestra por sí sola todos los requisitos. En Faro, un script puede encontrar «10:00», pero una persona debe confirmar que sea la hora pretendida.'), B('Ask what each piece of evidence actually covers.', 'Preguntá qué cubre realmente cada evidencia.')),
    F(B('The proposal moved', 'La propuesta avanzó'), B('A later commit can change what was reviewed. Whether an approval remains valid for merging depends on repository rules. Authors cannot approve their own pull request. Practicing alone still allows self-review of the diff, but not an independent approval.', 'Un commit posterior puede cambiar lo revisado. Que una aprobación siga habilitando el merge depende de las reglas del repositorio. El autor no puede aprobar su propio pull request. Practicar solo permite revisar tu diff, pero no una aprobación independiente.'), B('An approval has context, including the version reviewed.', 'Una aprobación tiene contexto, incluida la versión revisada.')),
  ], B('Toggle human approval and automated checks separately. Which missing evidence remains?', 'Alterná aprobación humana y controles automáticos por separado. ¿Qué evidencia sigue faltando?'), [
    Q(B('The test finds 10:00. What does it prove?', 'La prueba encuentra 10:00. ¿Qué demuestra?'), [B('That the library really opens then', 'Que la biblioteca realmente abre a esa hora'), B('That the checked text contains 10:00', 'Que el texto comprobado contiene 10:00'), B('That the whole project is correct', 'Que todo el proyecto es correcto')], 1, B('The test’s assertion defines its scope.', 'La afirmación de la prueba define su alcance.')),
    Q(B('Can the author provide the independent approval on their own PR?', '¿Puede el autor dar la aprobación independiente de su propio PR?'), [B('Yes, after a green check', 'Sí, después de un control verde'), B('Yes, on a small change', 'Sí, en un cambio chico'), B('No', 'No')], 2, B('Self-review is useful, but GitHub does not let authors approve their own pull requests.', 'La revisión propia sirve, pero GitHub no permite que el autor apruebe su propio pull request.')),
    Q(B('What makes a review comment actionable?', '¿Qué hace accionable un comentario de revisión?'), [B('A concrete concern, consequence and suggested direction', 'Una preocupación concreta, su consecuencia y una orientación'), B('Only saying “bad”', 'Decir solamente «mal»'), B('Counting changed lines', 'Contar líneas cambiadas')], 0, B('The author needs enough context to evaluate and address the concern.', 'El autor necesita contexto suficiente para evaluar y resolver la preocupación.')),
  ], [
    S(B('Prepare the review', 'Prepará la revisión'), B('Use the open proposal from lesson 11. Write two questions: are the hours supported, and are other notices consistent? Paper case: review the same hypothetical diff.', 'Usá la propuesta abierta de la lección 11. Escribí dos preguntas: ¿Hay respaldo para el horario y los demás avisos son coherentes? Caso en papel: revisá el mismo diff hipotético.'), B('A checklist of meaning, not command syntax.', 'Una lista de significado, no de sintaxis.')),
    S(B('Inspect the evidence', 'Inspeccioná la evidencia'), B('Read the diff yourself. If a willing collaborator is available, ask them to review your practice PR. Alone, record a self-review without claiming independent approval.', 'Leé el diff. Si tenés una persona dispuesta a colaborar, pedile que revise tu PR de práctica. Si estás solo, registrá una revisión propia sin afirmar aprobación independiente.'), B('Concerns refer to specific lines and acceptance criteria.', 'Las preocupaciones se refieren a líneas concretas y criterios de aceptación.')),
    S(B('Respond with reasoning', 'Respondé con razonamiento'), B('Draft a response to “the workshop still starts at 09:30”. Decide whether to adjust the notice or explain an exception. Record a focused follow-up change if needed.', 'Redactá una respuesta a «el taller todavía empieza a las 09:30». Decidí si ajustar el aviso o explicar una excepción. Registrá un cambio posterior enfocado si hace falta.'), B('The response resolves the actual concern with evidence.', 'La respuesta resuelve la preocupación real con evidencia.')),
    S(B('Review the new state', 'Revisá el estado nuevo'), B('Compare the final diff to the original criteria. If online, inspect review status after the new commit. Leave the PR open; rules may differ between repositories.', 'Compará el diff final con los criterios originales. Si estás en línea, inspeccioná el estado de revisión después del commit nuevo. Dejá el PR abierto; las reglas pueden variar entre repositorios.'), B('You can explain what was reviewed and what changed afterward.', 'Podés explicar qué se revisó y qué cambió después.')),
  ], 'reviews', 'github');

  add(3, 'integration-strategies', B('Same files, different histories', 'Mismos archivos, historias distintas'), B('Merge, squash and rebase preserve different kinds of context.', 'Merge, squash y rebase conservan distintos tipos de contexto.'), [
    F(B('Keep the meeting point', 'Conservá el punto de encuentro'), B('A merge commit joins histories with multiple parents. You can see where the feature line met main and retain its individual commits. This helps when the sequence of decisions on that line matters to future readers.', 'Un merge commit une historias con varios padres. Podés ver dónde la línea de trabajo se encontró con main y conservar sus commits individuales. Sirve cuando la secuencia de decisiones de esa línea importa a futuros lectores.'), B('Merge keeps the topology of the collaboration.', 'Merge conserva la forma de la colaboración.')),
    F(B('Keep the resulting decision', 'Conservá la decisión resultante'), B('Squashing records the proposal’s combined change as one new commit on the destination. The original feature commits are not ancestors through that integration. This can make main easier to read when a feature contains many temporary corrections.', 'Squash registra el cambio combinado de la propuesta como un commit nuevo en el destino. Los commits originales de la rama no quedan como ancestros por esa integración. Puede facilitar la lectura de main cuando una propuesta tiene muchas correcciones temporales.'), B('Squash trades intermediate history for one coherent result.', 'Squash intercambia historia intermedia por un resultado coherente.')),
    F(B('Replay onto another base', 'Reaplicá sobre otra base'), B('Rebase replays changes onto a new base, producing new commits when ancestry changes. Coordinate before rewriting work others use. GitHub’s rebase-and-merge creates new commit SHAs; its behavior is not identical to every local rebase case. Choose based on the history you want to maintain.', 'Rebase reaplica cambios sobre otra base y produce commits nuevos cuando cambia la ascendencia. Coordiná antes de reescribir trabajo que otros usan. Rebase-and-merge en GitHub crea SHAs nuevos; su comportamiento no es idéntico a todo rebase local. Elegí según la historia que querés mantener.'), B('Equal final files do not imply equal ancestry.', 'Archivos finales iguales no implican ascendencia igual.')),
  ], B('Select an integration strategy. Count parents and original commits reachable from the destination.', 'Elegí una estrategia de integración. Contá padres y commits originales alcanzables desde el destino.'), [
    Q(B('Which strategy normally creates a two-parent meeting point?', '¿Qué estrategia normalmente crea un encuentro con dos padres?'), [B('Squash', 'Squash'), B('Rebase', 'Rebase'), B('Merge commit', 'Merge commit')], 2, B('The parent links preserve the joined paths.', 'Los enlaces a padres conservan los caminos unidos.')),
    Q(B('Can squash and merge produce identical final files?', '¿Squash y merge pueden producir archivos finales idénticos?'), [B('Yes, while retaining different histories', 'Sí, conservando historias distintas'), B('No, files must differ', 'No, los archivos deben diferir'), B('Only with no changes', 'Solo sin cambios')], 0, B('Content equality and graph equality are different tests.', 'La igualdad de contenido y de grafo son comprobaciones distintas.')),
    Q(B('Why coordinate before rebasing shared work?', '¿Por qué coordinar antes de hacer rebase de trabajo compartido?'), [B('It disables GitHub forever', 'Deshabilita GitHub para siempre'), B('Others may depend on the old commit identities', 'Otros pueden depender de las identidades anteriores'), B('It always deletes all files', 'Siempre borra todos los archivos')], 1, B('Rewritten ancestry can leave collaborators with different versions of the same logical work.', 'La ascendencia reescrita puede dejar a colaboradores con versiones distintas del mismo trabajo lógico.')),
  ], local('strategies', B('The same feature is integrated three ways in separate repositories. Predict whether final files and parent counts will match.', 'La misma propuesta se integra de tres maneras en repositorios separados. Predecí si coincidirán archivos finales y cantidad de padres.'), B('Compare equal tree identifiers, the merge’s two parents, the squash’s single combined commit and replayed commit identities.', 'Compará identificadores de árbol iguales, dos padres del merge, un commit combinado del squash e identidades de commits reaplicados.'), B('Choose a strategy for Faro and defend what history you preserve and lose. The local test does not execute GitHub merge buttons.', 'Elegí una estrategia para Faro y defendé qué historia conservás y perdés. La prueba local no ejecuta los botones de GitHub.')), 'strategies');

  add(4, 'undo', B('Undo without losing the story', 'Deshacer sin perder la historia'), B('First identify whether the mistake is edited, recorded or shared.', 'Primero identificá si el error está editado, registrado o compartido.'), [
    F(B('Undo which state?', '¿Deshacer qué estado?'), B('An unfinished edit, a prepared change and a shared commit are different problems. Restoring a working file can discard unrecorded work. Removing a change from staging can leave the edit intact. State the desired result before choosing an undo operation.', 'Una edición pendiente, un cambio preparado y un commit compartido son problemas distintos. Restaurar un archivo de trabajo puede descartar trabajo sin registrar. Quitar un cambio de preparación puede dejar la edición intacta. Indicá el resultado deseado antes de elegir una operación.'), B('“Undo” is a goal, not one universal operation.', '«Deshacer» es un objetivo, no una operación universal.')),
    F(B('Add a corrective decision', 'Agregá una decisión correctiva'), B('Revert records a new commit that reverses an earlier commit’s effect. The original remains in history, explaining what happened. Reverting can conflict if later work depends on the changed content. It is useful for published work because it does not require moving the shared branch backward.', 'Revert registra un commit nuevo que invierte el efecto de uno anterior. El original queda en la historia y explica lo ocurrido. Revertir puede generar conflictos si trabajo posterior depende del contenido. Sirve para trabajo publicado porque no exige mover la rama compartida hacia atrás.'), B('Correcting history and erasing history are different intentions.', 'Corregir la historia y borrar historia son intenciones distintas.')),
    F(B('Moving a reference', 'Mover una referencia'), B('Reset can move the current branch and, depending on mode, change the index and working files. A hard reset can discard edits. Reflogs record local reference movements for a limited time; they are not permanent backup. Our lab uses only an isolated soft reset to compare mechanisms.', 'Reset puede mover la rama actual y, según el modo, cambiar el index y los archivos. Un hard reset puede descartar ediciones. Los reflogs registran movimientos locales de referencias por un tiempo limitado; no son respaldo permanente. El lab usa solo un soft reset aislado para comparar mecanismos.'), B('Protect unrecorded work before changing references or files.', 'Protegé trabajo sin registrar antes de cambiar referencias o archivos.')),
  ], B('Compare a new reversing commit with moving the branch back. Which preserves a public correction?', 'Compará un commit nuevo que invierte con mover la rama hacia atrás. ¿Cuál conserva una corrección pública?'), [
    Q(B('A bad commit was already shared. Which operation adds a traceable correction?', 'Un commit malo ya se compartió. ¿Qué operación agrega una corrección rastreable?'), [B('Delete the repository', 'Borrar el repositorio'), B('Revert', 'Revert'), B('Rename the branch', 'Renombrar la rama')], 1, B('Revert adds history expressing the reversal.', 'Revert agrega historia que expresa la inversión.')),
    Q(B('Does reverting remove the original commit from history?', '¿Revertir quita el commit original de la historia?'), [B('No', 'No'), B('Always', 'Siempre'), B('Only if its files are small', 'Solo si los archivos son chicos')], 0, B('Both the original decision and its correction remain.', 'Quedan la decisión original y su corrección.')),
    Q(B('Why is a local reflog not a permanent backup?', '¿Por qué un reflog local no es respaldo permanente?'), [B('It only stores screenshots', 'Solo guarda capturas'), B('It requires a pull request', 'Requiere un pull request'), B('Entries can expire and it belongs to that local repository', 'Las entradas pueden vencer y pertenece a ese repositorio local')], 2, B('Recovery facilities have scope and retention limits.', 'Las herramientas de recuperación tienen alcance y límites de retención.')),
  ], local('undo', B('After reverting the hours change, will the old content and the old history both be restored exactly?', 'Después de revertir el cambio de horarios, ¿se restaurarán exactamente el contenido y la historia anteriores?'), B('The old content returns through a new commit. In a separate branch the soft reset moves the pointer and keeps the prepared change.', 'El contenido anterior vuelve mediante un commit nuevo. En otra rama, soft reset mueve el puntero y conserva el cambio preparado.'), B('Explain why these operations can leave similar files but different explanations for teammates.', 'Explicá por qué estas operaciones pueden dejar archivos similares y explicaciones distintas para el equipo.')), 'undo');

  add(4, 'actions', B('Actions: automated evidence', 'Actions: evidencia automática'), B('An event starts work whose result has a defined scope.', 'Un evento inicia trabajo cuyo resultado tiene alcance definido.'), [
    F(B('Event, workflow, job, step', 'Evento, workflow, job, step'), B('A workflow describes automation. An event such as a pull request update can trigger it. Jobs run on runners, the machines executing the work. Steps within a job run in sequence; jobs can be independent or have dependencies. These names describe a flow of work.', 'Un workflow describe automatización. Un evento como actualizar un pull request puede dispararlo. Los jobs corren en runners, las máquinas que ejecutan el trabajo. Los steps de un job van en secuencia; los jobs pueden ser independientes o tener dependencias. Los nombres describen un flujo de trabajo.'), B('Trace why the run started and what it actually executed.', 'Seguí por qué empezó la ejecución y qué ejecutó realmente.')),
    F(B('A meaningful failing example', 'Un ejemplo que falla con sentido'), B('Our example checks that README contains 10:00. First try 09:00 and observe failure, then fix the text. A green run means that this assertion passed for that run’s revision. It does not establish opening hours in the real world or deploy the guide.', 'El ejemplo verifica que README contenga 10:00. Primero probá 09:00 y observá la falla; después corregí el texto. Una ejecución verde indica que esa afirmación pasó para la revisión de esa ejecución. No establece el horario del mundo real ni despliega la guía.'), B('A useful check can demonstrate both failure and success.', 'Un control útil puede demostrar falla y éxito.')),
    F(B('Automation has authority', 'La automatización tiene autoridad'), B('A workflow executes code with permissions and possibly secrets. Keep permissions narrow and review changes to workflows like other code. Untrusted contributions must not gain privileged secrets merely by opening a proposal. This course uses a small workflow with read-only repository contents permission.', 'Un workflow ejecuta código con permisos y posiblemente secretos. Limitá permisos y revisá cambios a workflows como cualquier código. Una contribución no confiable no debe obtener secretos privilegiados por abrir una propuesta. El curso usa un workflow chico con permiso de solo lectura del contenido.'), B('Automation is code plus authority, not just a green badge.', 'La automatización es código y autoridad, además de una señal verde.')),
  ], B('Toggle the assertion result. Which later steps may proceed, and what claim remains untested?', 'Alterná el resultado de la afirmación. ¿Qué pasos pueden seguir y qué afirmación sigue sin probarse?'), [
    Q(B('What does a green run for the hours check establish?', '¿Qué demuestra una ejecución verde del control de horarios?'), [B('The selected assertion passed for that revision', 'La afirmación elegida pasó para esa revisión'), B('All future commits will pass', 'Todos los commits futuros pasarán'), B('The guide was deployed', 'La guía fue desplegada')], 0, B('Evidence belongs to a particular check and revision.', 'La evidencia pertenece a un control y una revisión específicos.')),
    Q(B('Where do workflow jobs execute?', '¿Dónde se ejecutan los jobs del workflow?'), [B('Inside a branch name', 'Dentro de un nombre de rama'), B('On runners', 'En runners'), B('Inside the issue title', 'Dentro del título del issue')], 1, B('The runner provides the execution environment.', 'El runner provee el entorno de ejecución.')),
    Q(B('Why review a workflow change carefully?', '¿Por qué revisar cuidadosamente un cambio de workflow?'), [B('YAML always grants administrator access', 'YAML siempre da acceso administrador'), B('It cannot affect anything', 'No puede afectar nada'), B('It changes executable code and potentially its authority', 'Cambia código ejecutable y posiblemente su autoridad')], 2, B('What runs and what it can access are both part of the review.', 'Qué se ejecuta y a qué puede acceder forman parte de la revisión.')),
  ], [
    S(B('Read the included example', 'Leé el ejemplo incluido'), B('Open labs/examples/hours.yml and hours.test.mjs in the kit. Predict the result for README with 09:00. Online practice needs Actions enabled and available usage on your account; inspect that before running.', 'Abrí labs/examples/hours.yml y hours.test.mjs del kit. Predecí el resultado para README con 09:00. La práctica en línea necesita Actions habilitado y uso disponible en tu cuenta; inspeccionalo antes de ejecutar.'), B('One trigger on pull requests, one job, a test and narrow permissions.', 'Un disparador de pull requests, un job, una prueba y permisos limitados.')),
    S(B('Prepare the check', 'Prepará el control'), B('In faro-practice, add hours.yml at .github/workflows/hours.yml and hours.test.mjs at tests/hours.test.mjs on main. Then create a practice branch with README saying 09:00 and open a PR. Case study: draw the event and job without executing GitHub.', 'En faro-practice agregá hours.yml en .github/workflows/hours.yml y hours.test.mjs en tests/hours.test.mjs en main. Después creá una rama de práctica con README que diga 09:00 y abrí un PR. Caso de estudio: dibujá evento y job sin ejecutar GitHub.'), B('The failing case is explicit and separate from the earlier PR.', 'El caso que falla es explícito y separado del PR anterior.')),
    S(B('Observe failure, then success', 'Observá falla y después éxito'), B('Read the failing run log, change README to 10:00 on the proposal branch and inspect the new run. Case study: explain the two expected outcomes using the test source.', 'Leé el log de la ejecución fallida, cambiá README a 10:00 en la rama propuesta e inspeccioná la ejecución nueva. Caso de estudio: explicá ambos resultados esperados usando la prueba.'), B('Different revisions produce different results. Record run links only if actually executed.', 'Revisiones distintas producen resultados distintos. Registrá enlaces a ejecuciones solo si ocurrieron.')),
    S(B('Name the missing guarantee', 'Nombrá la garantía faltante'), B('Explain why this test could pass with an incorrect real schedule. Do not count the paper prediction as an Actions run. Leave the green PR open for the rules lesson.', 'Explicá por qué la prueba podría pasar con un horario real incorrecto. No cuentes la predicción en papel como ejecución de Actions. Dejá el PR verde abierto para la lección de reglas.'), B('A bounded statement of what the automated evidence proves.', 'Una afirmación acotada de qué demuestra la evidencia automática.')),
  ], 'actions', 'github');

  add(4, 'rules', B('Rules: turn agreements into gates', 'Reglas: convertir acuerdos en condiciones'), B('Access, review and checks answer different questions.', 'Acceso, revisión y controles responden preguntas distintas.'), [
    F(B('Who may do what?', '¿Quién puede hacer qué?'), B('Repository permissions control capabilities. Authentication establishes who you are; authorization determines what you may do. Being able to read a public repository does not mean you can push to it. A review approval is not a new repository permission.', 'Los permisos del repositorio controlan capacidades. La autenticación establece quién sos; la autorización determina qué podés hacer. Poder leer un repositorio público no implica poder publicar en él. Una aprobación de revisión no es un permiso nuevo del repositorio.'), B('Identity and permission are different questions.', 'Identidad y permiso son preguntas distintas.')),
    F(B('Require evidence at the destination', 'Exigí evidencia en el destino'), B('Repository rules can require pull requests, approvals or status checks before a target branch updates. Define which branch the rule targets and which check is required. Availability depends on plan and repository type; inspect your repository rather than assuming every option exists.', 'Las reglas pueden exigir pull requests, aprobaciones o controles antes de actualizar una rama destino. Definí qué rama alcanza la regla y qué control exige. La disponibilidad depende del plan y tipo de repositorio; inspeccioná el tuyo en vez de suponer que existe toda opción.'), B('A passing check and an enforced required check are different.', 'Un control aprobado y un control obligatorio aplicado son cosas distintas.')),
    F(B('The exception is part of the rule', 'La excepción forma parte de la regla'), B('Bypass permissions, rule activation and branch patterns affect enforcement. A configuration that targets another branch does not protect main. Review who may bypass a requirement and why; describe the actual boundary rather than claiming the repository is simply “protected”.', 'Los permisos de bypass, activación de reglas y patrones de rama afectan el cumplimiento de la regla. Una configuración que alcanza otra rama no protege main. Revisá quién puede omitir un requisito y por qué; describí el límite real en lugar de decir solamente «protegido».'), B('State the target, requirement and exceptions together.', 'Indicá destino, requisito y excepciones juntos.')),
  ], B('Toggle required review and passing checks. Can this policy allow integration with evidence missing?', 'Alterná revisión requerida y controles aprobados. ¿Esta política permite integrar con evidencia faltante?'), [
    Q(B('You can read a public repository. Can you necessarily push to it?', 'Podés leer un repositorio público. ¿Necesariamente podés publicar en él?'), [B('Yes', 'Sí'), B('Only after cloning', 'Solo después de clonar'), B('No', 'No')], 2, B('Read and write are different permissions.', 'Lectura y escritura son permisos distintos.')),
    Q(B('A check is green but optional. What is missing for enforcement?', 'Un control está verde pero es opcional. ¿Qué falta para exigirlo?'), [B('An applicable active requirement', 'Un requisito activo aplicable'), B('A longer branch name', 'Un nombre de rama más largo'), B('An extra README', 'Otro README')], 0, B('Evidence does not enforce its own use.', 'La evidencia no obliga por sí misma a ser usada.')),
    Q(B('A ruleset targets release/* only. Does that alone protect main?', 'Un ruleset alcanza solo release/*. ¿Eso por sí solo protege main?'), [B('Yes, rules apply everywhere', 'Sí, las reglas se aplican en todos lados'), B('No, the target does not match main', 'No, el destino no coincide con main'), B('Only after a clone', 'Solo después de clonar')], 1, B('Scope is part of the guarantee.', 'El alcance forma parte de la garantía.')),
  ], [
    S(B('Describe your intended policy', 'Describí la política pretendida'), B('For faro-practice, write: main needs a PR and a successful hours check. Add independent approval only if you have a second collaborator. Case study: use the same policy on paper.', 'Para faro-practice escribí: main necesita un PR y el control hours exitoso. Agregá aprobación independiente solo si tenés otra persona colaborando. Caso de estudio: usá la misma política en papel.'), B('An explicit destination and requirements.', 'Un destino y requisitos explícitos.')),
    S(B('Inspect available controls', 'Inspeccioná controles disponibles'), B('In repository settings, inspect rulesets or branch protection available for this practice repository. If unavailable on your plan, continue the labeled case study; do not upgrade just for this lesson.', 'En la configuración del repositorio inspeccioná rulesets o protección de ramas disponibles para esta práctica. Si tu plan no los ofrece, seguí con el caso de estudio identificado; no cambies de plan solo por esta lección.'), B('Record the actual availability; a missing option is not failed understanding.', 'Registrá la disponibilidad real; una opción ausente no indica falta de comprensión.')),
    S(B('Apply and challenge the policy', 'Aplicá y cuestioná la política'), B('In the practice repository only, configure an active rule for main using the existing hours check from lesson 15. Record any bypass actors. Push 09:00 again to see the blocked state, then 10:00 to see the gate open; no need to merge.', 'Solo en el repositorio de práctica, configurá una regla activa para main con el control hours existente de la lección 15. Registrá quién está en la lista de bypass. Volvé a poner 09:00 para ver el bloqueo y después 10:00 para ver que se habilita; no hace falta integrar.'), B('The PR is blocked with 09:00 and eligible with 10:00, or a clearly labeled prediction if no online rule was configured.', 'El PR queda bloqueado con 09:00 y habilitado con 10:00, o una predicción identificada si no configuraste la regla en línea.')),
    S(B('Explain the boundary', 'Explicá el límite'), B('Write who could still update the branch and under what exception. Explain why a rule cannot prove the real opening hours.', 'Escribí quién todavía podría actualizar la rama y con qué excepción. Explicá por qué una regla no puede demostrar el horario real.'), B('Target, requirements, exceptions and evidence limits are stated together.', 'Destino, requisitos, excepciones y límites de evidencia aparecen juntos.')),
  ], 'rules', 'github');

  add(5, 'releases', B('Tags, releases and deployments', 'Tags, releases y despliegues'), B('Naming a version, explaining it and running it are different events.', 'Nombrar una versión, explicarla y ejecutarla son eventos distintos.'), [
    F(B('A name for a chosen point', 'Un nombre para un punto elegido'), B('A tag such as v1.0 names a chosen point in history. Unlike a branch, it does not automatically advance with new commits. Teams usually treat published version tags as stable agreements, even though Git has operations that can move or delete tags. An annotated tag is an object with author, date and message; a lightweight tag is only a name.', 'Un tag como v1.0 nombra un punto elegido de la historia. A diferencia de una rama, no avanza automáticamente con commits nuevos. Los equipos suelen tratar los tags publicados como acuerdos estables, aunque Git tenga operaciones para moverlos o borrarlos. Un tag anotado es un objeto con autor, fecha y mensaje; un tag ligero es solo un nombre.'), B('Stability is a publishing policy, not an impossibility of change.', 'La estabilidad es una política de publicación, no una imposibilidad de cambio.')),
    F(B('Explain the delivered version', 'Explicá la versión entregada'), B('A GitHub release is based on a tag and can add notes and downloadable assets. Explain the user-visible changes, known limits and upgrade considerations. The tag names the source point; the release adds delivery context.', 'Una release de GitHub se basa en un tag y puede agregar notas y archivos descargables. Explicá cambios visibles, límites conocidos y consideraciones para actualizar. El tag nombra el punto de código; la release agrega contexto de entrega.'), B('A version number is less useful without its meaning.', 'Un número de versión sirve menos sin su significado.')),
    F(B('Running is another step', 'Ejecutar es otro paso'), B('A deployment puts a chosen artifact into an environment. Publishing a release does not by itself prove anything was deployed; a separately configured automation may connect them. Record the deployed revision and the environment so people can answer what is actually running.', 'Un despliegue coloca un artefacto elegido en un entorno. Publicar una release no prueba por sí solo que se desplegó algo; una automatización configurada aparte puede conectarlos. Registrá revisión desplegada y entorno para poder responder qué se está ejecutando.'), B('Source version, downloadable artifact and running system are distinct.', 'Versión de código, artefacto descargable y sistema en ejecución son distintos.')),
  ], B('Advance main after tagging v1.0. Does the tag follow it?', 'Adelantá main después de marcar v1.0. ¿El tag lo sigue?'), [
    Q(B('You add a commit to main after creating v1.0. Where does v1.0 point?', 'Agregás un commit a main después de crear v1.0. ¿Adónde apunta v1.0?'), [B('Automatically to the newest commit', 'Automáticamente al commit más nuevo'), B('To the previously selected point unless explicitly changed', 'Al punto elegido antes, salvo cambio explícito'), B('To every branch', 'A todas las ramas')], 1, B('Tags do not advance as branches do.', 'Los tags no avanzan como las ramas.')),
    Q(B('A GitHub release was published. What can you conclude about deployment?', 'Se publicó una release de GitHub. ¿Qué podés concluir sobre el despliegue?'), [B('Production updated', 'Producción se actualizó'), B('All users upgraded', 'Todos los usuarios actualizaron'), B('Nothing without evidence of a deployment process', 'Nada sin evidencia de un proceso de despliegue')], 2, B('A separate process must connect publication to an environment.', 'Un proceso separado debe conectar la publicación con un entorno.')),
    Q(B('What should release notes explain?', '¿Qué deberían explicar las notas de release?'), [B('Changes relevant to users and known limits', 'Cambios relevantes para usuarios y límites conocidos'), B('Only the author’s command history', 'Solo la historia de comandos del autor'), B('Only the tag spelling', 'Solo cómo se escribe el tag')], 0, B('Readers need to understand what adopting the version means.', 'Quienes leen necesitan entender qué implica adoptar la versión.')),
  ], local('tags', B('Create v1.0 and then a new main commit. Predict whether the two names still identify the same point.', 'Creá v1.0 y después otro commit en main. Predecí si ambos nombres siguen identificando el mismo punto.'), B('Compare the tag’s target with main after it advances. Read the guide at each reference.', 'Compará el destino del tag con main después de avanzar. Leé la guía en cada referencia.'), B('Write two release-note sentences for Faro. State why this experiment did not publish a GitHub release or deploy anything.', 'Escribí dos frases de notas de release para Faro. Indicá por qué este experimento no publicó una release en GitHub ni desplegó nada.')), 'releases');

  add(5, 'secrets', B('History remembers what you remove', 'La historia recuerda lo que quitás'), B('Ignoring a file and erasing exposure are different problems.', 'Ignorar un archivo y eliminar una exposición son problemas distintos.'), [
    F(B('Choose what belongs in history', 'Elegí qué pertenece a la historia'), B('Build outputs, local settings and credentials usually do not belong in a shared source history. A .gitignore rule guides which untracked files Git normally ignores. It does not automatically untrack a file already recorded.', 'Archivos generados, configuración local y credenciales normalmente no pertenecen a una historia de código compartida. Una regla .gitignore indica qué archivos sin seguimiento suele ignorar Git. No deja de seguir automáticamente un archivo ya registrado.'), B('Ignore rules act on selection, not past history.', 'Las reglas de ignorar actúan sobre la selección, no sobre el pasado.')),
    F(B('Deletion is a new snapshot', 'Borrar es una instantánea nueva'), B('Deleting a file and recording that deletion removes it from the new snapshot. Earlier commits can still contain it. A private repository also has readers and possible copies; privacy is not a substitute for keeping credentials out of source history.', 'Borrar un archivo y registrar la eliminación lo quita de la instantánea nueva. Commits anteriores todavía pueden contenerlo. Un repositorio privado también tiene lectores y posibles copias; la privacidad no reemplaza mantener credenciales fuera de la historia.'), B('Absent now does not mean absent from history.', 'Ausente ahora no significa ausente de la historia.')),
    F(B('Respond to the credential first', 'Atendé primero la credencial'), B('If a real credential is exposed, revoke or rotate it first. Then follow the host’s documented cleanup process and coordinate affected clones and forks. Rewriting one repository cannot guarantee removal from every copy. Our lab uses only an unmistakably fake marker.', 'Si se expone una credencial real, revocala o rotala primero. Después seguí el proceso documentado del proveedor y coordiná clones y forks afectados. Reescribir un repositorio no garantiza quitarla de toda copia. El lab usa solo un marcador inequívocamente ficticio.'), B('Stop the authority of the secret before cleaning its traces.', 'Detené la autoridad del secreto antes de limpiar sus rastros.')),
  ], B('Toggle deletion and ignore rules. Can the earlier snapshot still contain the fake marker?', 'Alterná eliminación y reglas de ignorar. ¿La instantánea anterior puede seguir conteniendo el marcador ficticio?'), [
    Q(B('A tracked file is added to .gitignore. Is its past content removed?', 'Un archivo seguido se agrega a .gitignore. ¿Se quita su contenido pasado?'), [B('No', 'No'), B('Yes, after refreshing', 'Sí, después de actualizar'), B('Only on GitHub', 'Solo en GitHub')], 0, B('Ignore rules do not rewrite recorded history.', 'Las reglas de ignorar no reescriben la historia registrada.')),
    Q(B('What is the first response to a leaked real credential?', '¿Cuál es la primera respuesta ante una credencial real filtrada?'), [B('Only delete the latest file', 'Solo borrar el archivo actual'), B('Revoke or rotate the credential', 'Revocar o rotar la credencial'), B('Rename the repository', 'Renombrar el repositorio')], 1, B('Removing text does not invalidate authority already copied elsewhere.', 'Quitar texto no invalida autoridad ya copiada en otro lugar.')),
    Q(B('Can cleaning one repository prove all copies are clean?', '¿Limpiar un repositorio prueba que todas las copias estén limpias?'), [B('Yes, copies share storage', 'Sí, las copias comparten almacenamiento'), B('Yes, if main is clean', 'Sí, si main está limpio'), B('No', 'No')], 2, B('Clones, forks and other retained copies have their own state.', 'Clones, forks y otras copias retenidas tienen su propio estado.')),
  ], local('secrets', B('A fake marker is recorded, ignored and then deleted. Will an earlier commit still show it?', 'Se registra, ignora y después borra un marcador ficticio. ¿Un commit anterior todavía lo mostrará?'), B('Observe that .gitignore does not untrack the file, then that deletion leaves the old snapshot readable. No real credentials are used.', 'Observá que .gitignore no deja de seguir el archivo y después que borrarlo deja legible la instantánea vieja. No se usan credenciales reales.'), B('Explain why revocation and repository cleanup solve different parts of an exposure.', 'Explicá por qué revocar y limpiar el repositorio resuelven partes distintas de una exposición.')), 'secrets');

  add(5, 'capstone', B('A change you can defend', 'Un cambio que podés defender'), B('Take the library guide from reported problem to an explained delivery.', 'Llevá la guía de la biblioteca del problema reportado a una entrega explicada.'), [
    F(B('Start with a state map', 'Empezá con un mapa de estados'), B('The library changes its winter schedule again. A teammate is editing the workshop notice while you update the guide. Draw local copies, remote references and the proposed branches. Identify the acceptance criteria before choosing operations.', 'La biblioteca vuelve a cambiar el horario de invierno. Otra persona edita el aviso del taller mientras vos actualizás la guía. Dibujá copias locales, referencias remotas y ramas propuestas. Identificá criterios de aceptación antes de elegir operaciones.'), B('A good plan states what each person knows and intends.', 'Un buen plan dice qué sabe y qué pretende cada persona.')),
    F(B('Introduce a disagreement deliberately', 'Introducí un desacuerdo a propósito'), B('Make the guide say 10:00 and the workshop say 09:30. The text can merge cleanly and still fail the acceptance criteria. Explain whether the workshop is an exception or needs a new time, then record the decision and evidence in the proposal.', 'Hacé que la guía diga 10:00 y el taller 09:30. El texto puede pasar por un merge sin conflicto e incumplir los criterios. Explicá si el taller es una excepción o necesita otro horario, y registrá decisión y evidencia en la propuesta.'), B('Detect a meaning conflict even when Git finds no text conflict.', 'Detectá un conflicto de significado aunque Git no encuentre uno textual.')),
    F(B('Deliver a traceable decision', 'Entregá una decisión rastreable'), B('Choose an integration strategy, verify the resulting guide and name a version if useful. Explain how you would revert a mistaken published change. Hand another person the issue, proposal, evidence and release notes; they should be able to reconstruct the decision.', 'Elegí una estrategia de integración, verificá la guía resultante y nombrá una versión si sirve. Explicá cómo revertirías un cambio publicado incorrecto. Entregale a otra persona issue, propuesta, evidencia y notas de release; debería poder reconstruir la decisión.'), B('Completion means an explainable result, not a sequence of clicks.', 'Terminar significa un resultado explicable, no una secuencia de clics.')),
  ], B('Walk through problem, proposal, evidence and delivery. Remove one link and explain what becomes harder to trust.', 'Recorré problema, propuesta, evidencia y entrega. Quitá un enlace y explicá qué se vuelve más difícil de confiar.'), [
    Q(B('All automated checks pass but the workshop starts before opening. What now?', 'Todos los controles pasan pero el taller empieza antes de abrir. ¿Qué hacés?'), [B('Merge because green is enough', 'Hacer merge porque el verde alcanza'), B('Resolve and verify the domain disagreement', 'Resolver y verificar el desacuerdo del dominio'), B('Delete the issue', 'Borrar el issue')], 1, B('Automated checks do not replace criteria they never tested.', 'Los controles automáticos no reemplazan criterios que nunca probaron.')),
    Q(B('Which handoff best preserves understanding?', '¿Qué entrega conserva mejor la comprensión?'), [B('Only the list of commands', 'Solo la lista de comandos'), B('Only a green screenshot', 'Solo una captura verde'), B('Problem, change, evidence, limits and recovery plan', 'Problema, cambio, evidencia, límites y recuperación')], 2, B('A future maintainer needs the decision and its boundaries.', 'Quien mantenga el proyecto necesita la decisión y sus límites.')),
    Q(B('You cannot access GitHub today. What can you honestly complete?', 'Hoy no podés acceder a GitHub. ¿Qué podés completar honestamente?'), [B('A labeled case study and local Git evidence', 'Un caso de estudio identificado y evidencia local de Git'), B('A verified online approval', 'Una aprobación en línea verificada'), B('A verified deployment', 'Un despliegue verificado')], 0, B('Learning can continue while evidence remains accurately labeled.', 'Podés seguir aprendiendo y mantener la evidencia correctamente identificada.')),
  ], [
    S(B('Define the change', 'Definí el cambio'), B('In faro-practice, open a new issue for 10:00 opening with a consistent workshop notice. Create a proposal branch and record the guide and notice as purposeful commits. Close the earlier practice PRs with a note, or merge the 10:00 one as part of this delivery. Without an account, draw the same histories and write a case-study proposal.', 'En faro-practice abrí otro issue para apertura a las 10:00 con un aviso de taller coherente. Creá una rama propuesta y registrá guía y aviso en commits con propósito. Cerrá los PR de práctica anteriores con una nota, o integrá el de 10:00 como parte de esta entrega. Sin cuenta, dibujá las mismas historias y escribí una propuesta de caso de estudio.'), B('A need, a destination branch and inspectable snapshots.', 'Una necesidad, una rama destino e instantáneas inspeccionables.')),
    S(B('Challenge the result', 'Cuestioná el resultado'), B('Introduce the 09:30 workshop contradiction, then explain and correct it. Use the hours check if configured and inspect its limits. Obtain a collaborator review if available; otherwise label self-review honestly.', 'Introducí la contradicción del taller a las 09:30, después explicala y corregila. Usá el control hours si está configurado e inspeccioná sus límites. Obtené revisión de otra persona si está disponible; de lo contrario identificá la revisión propia honestamente.'), B('Both textual and domain consistency are considered.', 'Se consideran coherencia textual y del dominio.')),
    S(B('Integrate with a reason', 'Integrá con un motivo'), B('Choose merge, squash or rebase and write why. In your practice repository, integrate only when its actual requirements are satisfied; inspect main afterward. Case study: draw the resulting graph and content.', 'Elegí merge, squash o rebase y escribí por qué. En tu repositorio de práctica integrá cuando se cumplan sus requisitos reales; inspeccioná main después. Caso de estudio: dibujá grafo y contenido resultantes.'), B('The final content meets the issue criteria, with the chosen ancestry.', 'El contenido final cumple los criterios del issue con la ascendencia elegida.')),
    S(B('Teach the decision back', 'Explicá la decisión a otra persona'), B('Write a short delivery note with version, change, evidence, untested limits and how to reverse it. Score yourself using the rubric in labs/CAPSTONE.md. Mark each piece as observed, executed or simulated.', 'Escribí una nota de entrega con versión, cambio, evidencia, límites sin probar y cómo revertirlo. Evaluá tu trabajo con la rúbrica de labs/CAPSTONE.md. Marcá cada evidencia como observada, ejecutada o simulada.'), B('Another person can reconstruct your reasoning without a command transcript.', 'Otra persona puede reconstruir tu razonamiento sin una transcripción de comandos.')),
  ], 'flow', 'github');
  return { version: '1.1.0', date: '2026-10-18', git: '2.51.0', units, lessons };
})();
